package com.agacostays.payroll.service.impl; import com.agacostays.payroll.dto.request.*;import com.agacostays.payroll.dto.response.*;import com.agacostays.payroll.entity.*;import com.agacostays.payroll.enums.*;import com.agacostays.payroll.exception.*;import com.agacostays.payroll.mapper.*;import com.agacostays.payroll.repository.*;import com.agacostays.payroll.service.*;import org.springframework.stereotype.Service;import jakarta.transaction.Transactional;
@Service public class StaffBankAccountServiceImpl implements StaffBankAccountService{final StaffBankAccountRepository repo;final StaffBankAccountMapper mapper;public StaffBankAccountServiceImpl(StaffBankAccountRepository r,StaffBankAccountMapper m){repo=r;mapper=m;}public StaffBankAccountResponse save(Long id,StaffBankAccountRequest r,Long actor){if(repo.findByStaffId(id).filter(x->x.getStatus()==BankAccountStatus.ACTIVE).isPresent())throw new DuplicateResourceException("Active bank account already exists");StaffBankAccount x=repo.findByStaffId(id).orElse(StaffBankAccount.builder().staffId(id).build());apply(x,r,actor);return mapper.toResponse(repo.save(x));}public StaffBankAccountResponse get(Long id){return repo.findByStaffId(id).filter(x->x.getStatus()==BankAccountStatus.ACTIVE).map(mapper::toResponse).orElseThrow(()->new ResourceNotFoundException("Bank account not found for staff "+id));}@Transactional public StaffBankAccountResponse update(Long id,StaffBankAccountRequest r,Long actor){StaffBankAccount x=repo.findByStaffId(id).orElseThrow(()->new ResourceNotFoundException("Bank account not found for staff "+id));apply(x,r,actor);return mapper.toResponse(repo.save(x));}@Transactional public void deactivate(Long id){StaffBankAccount x=repo.findByStaffId(id).orElseThrow(()->new ResourceNotFoundException("Bank account not found for staff "+id));x.setStatus(BankAccountStatus.INACTIVE);repo.save(x);}private void apply(StaffBankAccount x,StaffBankAccountRequest r,Long actor){x.setAccountHolderName(r.accountHolderName());x.setBankName(r.bankName());x.setAccountNumber(r.accountNumber());x.setIfscCode(r.ifscCode());x.setBranchName(r.branchName());x.setAccountType(r.accountType());x.setStatus(BankAccountStatus.ACTIVE);if(x.getCreatedBy()==null)x.setCreatedBy(actor);}}
